<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">Where</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">p</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E5C07B;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">IsActive</span><span style="color:#ABB2BF;">)       </span><span style="color:#7F848E;font-style:italic;">// 过滤</span></span>
